        libs = os.path.join(base, 'lib', 'python3.11', 'site-packages')
        print(f"Checking {libs}...")
        if os.path.exists(libs):
            for p in os.listdir(libs):
                if 'prime' in p.lower() or 'agent' in p.lower():
                    print(f"  Found: {p}")
